using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(Uri = "config://app/settings", Name = "App Settings",
        Description = "Returns the current application configuration")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "production",
            Version = "1.0.0",
            Features = new { DarkMode = true, BetaAccess = false },
            MaxConnections = 100
        };

        return System.Text.Json.JsonSerializer.Serialize(config,
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(Uri = "config://app/endpoints", Name = "API Endpoints",
        Description = "Returns available API endpoint configuration")]
    public static string GetEndpoints()
    {
        var endpoints = new
        {
            Api = "https://api.example.com/v1",
            Auth = "https://auth.example.com",
            Webhooks = "https://hooks.example.com"
        };

        return System.Text.Json.JsonSerializer.Serialize(endpoints,
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool, Description("Returns the current server status and uptime")]
    public static string GetStatus()
    {
        return $"Server is running. Started at: {Program.StartTime:O}, " +
               $"Uptime: {DateTime.UtcNow - Program.StartTime:g}";
    }

    [McpServerTool, Description("Echoes back the provided message")]
    public static string Echo([Description("The message to echo")] string message)
    {
        return $"Echo: {message}";
    }
}

